package com.xianshuyuan.scm.customer.service;
import com.xianshuyuan.scm.customer.entity.CustomerAgreementPriceEntity; import com.xianshuyuan.scm.customer.mapper.CustomerAgreementPriceMapper; import com.xianshuyuan.scm.product.mapper.ProductSkuMapper; import org.springframework.stereotype.Service; import java.time.OffsetDateTime; import java.util.*; import java.util.function.Function; import java.util.stream.Collectors;
@Service public class CustomerPriceResolver { private final CustomerService customers; private final CustomerAgreementPriceMapper prices; private final ProductSkuMapper skus; private final OrderableSkuQueryService orderable; public CustomerPriceResolver(CustomerService c,CustomerAgreementPriceMapper p,ProductSkuMapper s,OrderableSkuQueryService o){customers=c;prices=p;skus=s;orderable=o;} public List<ResolvedCustomerPrice> resolve(long customerId,List<Long> skuIds,OffsetDateTime at){if(skuIds.isEmpty())return List.of();var rows=orderable.requireOrderable(customerId,skuIds);Map<Long,CustomerAgreementPriceEntity> agreement=prices.selectEffective(customerId,skuIds,at).stream().collect(Collectors.toMap(CustomerAgreementPriceEntity::getSkuId,Function.identity(),(a,b)->a));Map<Long,com.xianshuyuan.scm.product.entity.ProductSkuEntity> byId=rows.stream().collect(Collectors.toMap(com.xianshuyuan.scm.product.entity.ProductSkuEntity::getId,Function.identity()));return skuIds.stream().map(id->{var a=agreement.get(id);return a==null?new ResolvedCustomerPrice(id,byId.get(id).getMarketPrice(),PriceSource.MARKET,null):new ResolvedCustomerPrice(id,a.getUnitPrice(),PriceSource.AGREEMENT,a.getId());}).toList();}}
